LiteralVerification.Code:
$name = 'McpServer'    # manifest.service.name
$port = 7147           # manifest.endpoint.port
$install = 'C:\ProgramData\McpServer'

$svc = Get-Service -Name $name -ErrorAction Stop
if ($svc.Status -ne 'Running') { throw "Service status=$($svc.Status)" }
$wmi = Get-CimInstance Win32_Service -Filter "Name='$name'"
$expectedExe = [IO.Path]::GetFullPath((Join-Path $install 'McpServer.Support.Mcp.exe'))
$expectedUrls = "http://+:$port"
# Strict canonical UpdateService ImagePath: BOTH exe and --urls value fully quoted, balanced, no trailing junk.
# Rejects unbalanced quotes, unquoted paths with spaces, .exe.old, 71470, exe-as-later-arg, duplicate --urls.
$actual = $wmi.PathName.Trim()
$m = [regex]::Match($actual, '^"(?<exe>[^"]+\.exe)"\s+--urls\s+"(?<urls>[^"]+)"\s*$', 'IgnoreCase')
if (-not $m.Success) { $form = '"{0}" --urls "{1}"' -f 'exe','http://+:port'; throw "ImagePath must be fully quoted UpdateService form: $form; got: $actual" }
$actualExe = [IO.Path]::GetFullPath($m.Groups['exe'].Value)
$actualUrls = $m.Groups['urls'].Value
if (-not $actualExe.Equals($expectedExe, [StringComparison]::OrdinalIgnoreCase)) { throw "ImagePath exe mismatch: $actualExe" }
if (-not $actualUrls.Equals($expectedUrls, [StringComparison]::OrdinalIgnoreCase)) { throw "ImagePath --urls mismatch: $actualUrls" }
$canonical = '"{0}" --urls "{1}"' -f $expectedExe, $expectedUrls
$normalized = '"{0}" --urls "{1}"' -f $actualExe, $actualUrls
if (-not $normalized.Equals($canonical, [StringComparison]::OrdinalIgnoreCase)) { throw "ImagePath canonical mismatch" }
$startOk = @('LocalSystem','NT AUTHORITY\SYSTEM','.\LocalSystem') -contains $wmi.StartName
if (-not $startOk) { throw "StartName=$($wmi.StartName) not LocalSystem" }
if ($wmi.ProcessId -le 0) { throw 'Service ProcessId missing' }
if (-not (Test-Path $expectedExe)) { throw 'exe missing' }
if (-not (Test-Path "$install\.mcpservice-deployment.json")) { throw 'deployment manifest missing' }
if (-not (Test-Path "$install\appsettings.yaml")) { throw 'appsettings.yaml missing' }
# Provider/DB: require resolved identity with provenance; yaml alone insufficient (incl. SQLite ConnectionString vs DataSource)
$listeners = @(Get-NetTCPConnection -LocalPort $port -State Listen -EA SilentlyContinue | Where-Object OwningProcess -eq $wmi.ProcessId)
if ($listeners.Count -lt 1) { throw "No listener on $port owned by PID $($wmi.ProcessId)" }
# Evidence: assert reject for unbalanced quotes, unquoted Program Files path, .exe.old, http://+:71470, exe-as-later-arg.
# Accept only fully quoted canonical form matching UpdateService GetServiceImagePath.
# Trust/nonce against endpoint.baseUrl; per-agent smokes (Phase 4)

LiteralVerification.Harness:
$script:hvDraftText = [IO.File]::ReadAllText($script:hvDraft)
$script:hvFenceMatch = [regex]::Match($script:hvDraftText, '(?ms)^### Verify \(Windows\)\r?\n\s*' + [regex]::Escape((([string][char]96)*3)+'powershell') + '\r?\n(?<code>.*?)^' + [regex]::Escape(([string][char]96)*3) + '\s*$')
if (-not $script:hvFenceMatch.Success) { throw 'Exact Verify Windows fence not found' }
$script:hvVerifyCode = $script:hvFenceMatch.Groups['code'].Value
$script:hvTokens = $null
$script:hvParseErrors = $null
$null = [Management.Automation.Language.Parser]::ParseInput($script:hvVerifyCode,[ref]$script:hvTokens,[ref]$script:hvParseErrors)
$script:hvVerifyBlock = [scriptblock]::Create($script:hvVerifyCode)
$script:hvFenceHash = [Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($script:hvVerifyCode)))
$script:hvFenceChanges = @(Compare-Object ($script:hvPrior.LiteralVerification.Code -split '\r?\n') ($script:hvVerifyCode -split '\r?\n'))
$script:hvImageCases = @($script:hvPrior.IsolatedImagePath.Results | ForEach-Object { [pscustomobject]@{Id=$_.Id; ImagePath=$_.ImagePath; Expected=if($_.Id -eq 'canonical-spaces'){$false}else{$_.Expected}; Status='Running'; StartName='LocalSystem'; ServicePid=24680; ListenerPid=24680; ListenerPresent=$true; MissingPath=$null} })
$script:hvServiceCases = @(
 [pscustomobject]@{Id='system-alias';StartName='NT AUTHORITY\SYSTEM';Expected=$true},
 [pscustomobject]@{Id='wrong-account';StartName='NT AUTHORITY\NetworkService';Expected=$false},
 [pscustomobject]@{Id='stopped';Status='Stopped';Expected=$false},
 [pscustomobject]@{Id='wrong-listener-pid';ListenerPid=13579;Expected=$false},
 [pscustomobject]@{Id='zero-service-pid';ServicePid=0;Expected=$false},
 [pscustomobject]@{Id='missing-exe';MissingPath='C:\ProgramData\McpServer\McpServer.Support.Mcp.exe';Expected=$false},
 [pscustomobject]@{Id='missing-manifest';MissingPath='C:\ProgramData\McpServer\.mcpservice-deployment.json';Expected=$false},
 [pscustomobject]@{Id='missing-yaml';MissingPath='C:\ProgramData\McpServer\appsettings.yaml';Expected=$false},
 [pscustomobject]@{Id='no-listener';ListenerPresent=$false;Expected=$false}
)
$script:hvLiteralResults = @(
foreach ($hvCase in @($script:hvImageCases)+@($script:hvServiceCases)) {
 & {
  param($Case,$Block)
  $hvMockData = @{
   ImagePath='"C:\ProgramData\McpServer\McpServer.Support.Mcp.exe" --urls "http://+:7147"'
   Status='Running'; StartName='LocalSystem'; ServicePid=24680; ListenerPid=24680
   ListenerPresent=$true; MissingPath=$null
  }
  foreach($p in $Case.PSObject.Properties) { $hvMockData[$p.Name]=$p.Value }
  $trace = [Collections.Generic.List[string]]::new()
  function Get-Service {
   [CmdletBinding()]param([string]$Name)
   $trace.Add("Get-Service Name=$Name")
   if($Name -ne 'McpServer'){throw 'Harness unexpected service name'}
   [pscustomobject]@{Status=$hvMockData.Status}
  }
  function Get-CimInstance {
   [CmdletBinding()]param([string]$ClassName,[string]$Filter)
   $trace.Add("Get-CimInstance Class=$ClassName Filter=$Filter")
   if($ClassName -ne 'Win32_Service' -or $Filter -ne "Name='McpServer'"){throw 'Harness unexpected CIM request'}
   [pscustomobject]@{PathName=$hvMockData.ImagePath;StartName=$hvMockData.StartName;ProcessId=$hvMockData.ServicePid}
  }
  function Test-Path {
   [CmdletBinding()]param([string]$Path)
   $trace.Add("Test-Path Path=$Path")
   $Path -ne $hvMockData.MissingPath
  }
  function Get-NetTCPConnection {
   [CmdletBinding()]param([int]$LocalPort,[string]$State)
   $trace.Add("Get-NetTCPConnection Port=$LocalPort State=$State")
   if($LocalPort -ne 7147 -or $State -ne 'Listen'){throw 'Harness unexpected listener query'}
   if($hvMockData.ListenerPresent){[pscustomobject]@{OwningProcess=$hvMockData.ListenerPid}}
  }
  $accepted=$false; $errorText=$null
  try { $null = & $Block; $accepted=$true } catch { $errorText=$_.Exception.Message }
  [pscustomobject]@{Id=$Case.Id;Expected=$Case.Expected;Accepted=$accepted;Pass=($accepted -eq $Case.Expected);Error=$errorText;ImagePath=$hvMockData.ImagePath;Trace=@($trace);Scope='Entire unmodified draft Verify Windows fence, in-memory command mocks'}
 } $hvCase $script:hvVerifyBlock
}
)
[pscustomobject]@{
 ParserErrors=@($script:hvParseErrors).Count; ScriptBlockCreated=($null -ne $script:hvVerifyBlock)
 FenceSHA256=$script:hvFenceHash; ChangedFenceLines=$script:hvFenceChanges
 Total=$script:hvLiteralResults.Count;Passed=@($script:hvLiteralResults | Where-Object Pass).Count
 Failed=@($script:hvLiteralResults | Where-Object {-not $_.Pass}).Count
} | ConvertTo-Json -Depth 5
$script:hvLiteralResults | Select-Object Id,Expected,Accepted,Pass,Error | ConvertTo-Json -Depth 5
$script:hvLiteralResults | Where-Object Id -eq 'canonical' | ConvertTo-Json -Depth 5
